    // Calculate maximum possible wins in the ideal arrangement
    // Rock beats Scissors, Paper beats Rock, Scissors beats Paper
    // We can assign rounds optimally: use our rock against their scissors, paper against rock, scissors against paper
    int max_wins = min(r[0], opp[2]) + min(r[1], opp[0]) + min(r[2], opp[1]);
