int compute_max_wins(int r1, int s1, int p1, int r2, int s2, int p2) {
    vector<int> r = {r1, s1, p1};
    vector<int> opp = {r2, s2, p2};
    int total_wins = 0;
    // Simulate optimal assignment for each round type
    // First, match moves directly: use rock vs rock, paper vs paper, scissors vs scissors to eliminate same-type
    for (int i = 0; i < 3; i++) {
        int same = min(r[i], opp[i]);
        r[i] -= same;
        opp[i] -= same;
    }
    // Then use remaining moves: for rock, try scissors next; for paper, try rock; for scissors, try paper
    // We need circular matching: rock(0) beats scissors(2), paper(1) beats rock(0), scissors(2) beats paper(1)
    // For leftover rock(r[0]), try to beat leftover scissors(opp[2])
    if (r[0] > 0) {
        int use = min(r[0], opp[2]);
        total_wins += use;
        r[0] -= use;
        opp[2] -= use;
    }
    // For leftover paper(r[1]), try to beat leftover rock(opp[0])
    if (r[1] > 0) {
        int use = min(r[1], opp[0]);
        total_wins += use;
        r[1] -= use;
        opp[0] -= use;
    }
    // For leftover scissors(r[2]), try to beat leftover paper(opp[1])
    if (r[2] > 0) {
        int use = min(r[2], opp[1]);
        total_wins += use;
        r[2] -= use;
        opp[1] -= use;
    }
    return total_wins;
}

