pair<int, int> process_matches(int r1, int s1, int p1, int r2, int s2, int p2) {
    // Calculate the best-case scenario (maximum wins)
    int best_wins = 0;
    // Use rock to beat scissors
    int rock_vs_scissors = min(r1, p2);
    best_wins += rock_vs_scissors;
    r1 -= rock_vs_scissors;
    p2 -= rock_vs_scissors;
    // Use paper to beat rock
    int paper_vs_rock = min(p1, r2);
    best_wins += paper_vs_rock;
    p1 -= paper_vs_rock;
    r2 -= paper_vs_rock;
    // Use scissors to beat paper
    int scissors_vs_paper = min(s1, s2);
    best_wins += scissors_vs_paper;
    s1 -= scissors_vs_paper;
    s2 -= scissors_vs_paper;

    // Now calculate worst-case scenario (minimum wins remaining after optimal matching)
    // Build a simulation of residual counts after optimal match
    vector<int> r_rem = {r1, s1, p1};
    vector<int> opp_rem = {r2, s2, p2};

    // First eliminate same-type matchups (draws)
    for (int i = 0; i < 3; i++) {
        int match = min(r_rem[i], opp_rem[i]);
        r_rem[i] -= match;
        opp_rem[i] -= match;
    }

    // Then try to convert remaining to wins
    // Rock(0) beats scissors(2), paper(1) beats rock(0), scissors(2) beats paper(1)
    int total_min_wins = 0;
    // Try rock vs scissors
    if (r_rem[0] > 0 && opp_rem[2] > 0) {
        int use = min(r_rem[0], opp_rem[2]);
        total_min_wins += use;
        r_rem[0] -= use;
        opp_rem[2] -= use;
    }
    // Try paper vs rock
    if (r_rem[1] > 0 && opp_rem[0] > 0) {
        int use = min(r_rem[1], opp_rem[0]);
        total_min_wins += use;
        r_rem[1] -= use;
        opp_rem[0] -= use;
    }
    // Try scissors vs paper
    if (r_rem[2] > 0 && opp_rem[1] > 0) {
        int use = min(r_rem[2], opp_rem[1]);
        total_min_wins += use;
        r_rem[2] -= use;
        opp_rem[1] -= use;
    }

    return make_pair(total_min_wins, best_wins);
}

