#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
using namespace std;

typedef long long ll;

const ll INF = 1e18;
const ll MOD = 1e9 + 7;

class Dinic {
public:
    int n;
    vector<vector<vector<ll>>> links;
    vector<int> depth;
    vector<int> progress;
    vector<pair<int, int>> pos;

    Dinic(int n) : n(n) {
        links.resize(n);
        depth.resize(n);
        progress.resize(n);
    }

    void add_edge(int _from, int to, ll cap) {
        pos.push_back(make_pair(_from, links[_from].size()));
        links[_from].push_back({cap, (ll)to, (ll)links[to].size()});
        links[to].push_back({0, (ll)_from, (ll)links[_from].size() - 1});
    }

    void bfs(int s) {
        fill(depth.begin(), depth.end(), -1);
        depth[s] = 0;
        queue<int> q;
        q.push(s);
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (auto& edge : links[v]) {
                ll cap = edge[0];
                int to = (int)edge[1];
                if (cap > 0 && depth[to] < 0) {
                    depth[to] = depth[v] + 1;
                    q.push(to);
                }
            }
        }
    }

    ll dfs(int v, int t, ll flow) {
        if (v == t) return flow;
        for (int i = progress[v]; i < links[v].size(); i++) {
            progress[v] = i;
            vector<ll>& edge = links[v][i];
            ll cap = edge[0];
            int to = (int)edge[1];
            int rev = (int)edge[2];
            if (cap == 0 || depth[v] >= depth[to]) continue;
            ll d = dfs(to, t, min(flow, cap));
            if (d == 0) continue;
            links[v][i][0] -= d;
            links[to][rev][0] += d;
            return d;
        }
        return 0;
    }

    ll flow(int s, int t) {
        ll flow = 0;
        while (true) {
            bfs(s);
            if (depth[t] < 0) return flow;
            fill(progress.begin(), progress.end(), 0);
            ll current_flow = dfs(s, t, INF);
            while (current_flow > 0) {
                flow += current_flow;
                current_flow = dfs(s, t, INF);
            }
        }
    }

    pair<int, pair<ll, ll>> get_edge(int i) {
        int from = pos[i].first;
        int idx = pos[i].second;
        vector<ll>& e = links[from][idx];
        vector<ll>& re = links[(int)e[1]][(int)e[2]];
        return make_pair(from, make_pair(e[0] + re[0], re[0]));
    }

    vector<pair<int, pair<ll, ll>>> get_edges() {
        vector<pair<int, pair<ll, ll>>> res;
        for (int i = 0; i < pos.size(); i++) {
            res.push_back(get_edge(i));
        }
        return res;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M = 3;
    cin >> N;
    vector<ll> A(M), B(M);
    for (int i = 0; i < M; i++) cin >> A[i];
    for (int i = 0; i < M; i++) cin >> B[i];

    ll ans1 = 0;
    for (int i = 0; i < M; i++) {
        ans1 += min(A[i], B[(i+1)%M]);
    }

    Dinic dinic(2*M+2);
    int s = 2*M;
    int t = 2*M + 1;
    for (int i = 0; i < M; i++) {
        dinic.add_edge(s, i, N);
        dinic.add_edge(M+i, t, B[i]);
        dinic.add_edge(i, M+i, A[i]);
        dinic.add_edge(i, M+(i-1+M)%M, A[i]);
    }
    ll ans2 = N - dinic.flow(s, t);

    cout << ans2 << " " << ans1 << endl;

    return 0;
}

