        long long limit = (long long)sqrt(i) + 1;

        for (long long f = 2; f < min(limit, i + 1); f++) {
            if (i / f >= 1) {
                cur = (cur + mem[i / f]) % mod;
            }
        }

        long long be = i;
        long long j = 1;
        while (j <= i / limit) {
            long long next_val = i / (j + 1);
            cur = (cur + (be - next_val) * mem[j]) % mod;
            be = next_val;
