    std::vector<long long> mem(n + 1, 0);
    if (n >= 1) {
        mem[1] = 1;
    }

    for (int num = 2; num <= n; num++) {
        long long total = 1;  // start with mem[1] contribution

        // Iterate through proper divisors f (2 to floor(sqrt(num)))
        int max_f = static_cast<int>(std::sqrt(num)) + 1;
        for (int divisor = 2; divisor < max_f; divisor++) {
            int q = num / divisor;
            if (q > 0) {
                total = (total + mem[q]) % mod;
            }
        }

        // Use harmonic series trick for large quotients
        int prev = num;
        int k = 1;
        while (k <= num / max_f) {
            int next_q = num / (k + 1);
            int count = prev - next_q;
            total = (total + static_cast<long long>(count) * mem[k]) % mod;
            prev = next_q;
            k++;
        }

        mem[num] = total;
    }

    std::cout << (n > 0 ? mem[n] % mod : 0) << std::endl;

    return 0;
}

