int main() {
    int n, M;
    cin >> n >> M;

    // Precompute divisors for each number up to n
    vector<vector<int>> D(n + 1);
    for (int d = 2; d <= n; d++) {
        for (int dst = 2 * d; dst <= n; dst += d) {
            D[dst].push_back(d);
        }
    }

    // Compute F array using dynamic programming
    vector<long long> F(n + 1, 0);
    F[1] = 1;
    if (n >= 2) {
        F[2] = 2;
    }

    for (int x = 3; x <= n; x++) {
        // Base recurrence part
        long long base_val = (2 * F[x - 1] + F[x / (x - 1)]) % M;

        // Sum over divisors
        long long divisor_sum = 0;
        for (int d : D[x]) {
            if (2 <= d && d <= x - 2) {
                divisor_sum = (divisor_sum + F[x / d] - F[(x - 1) / d]) % M;
            }
        }

        F[x] = (base_val + divisor_sum) % M;
        // Ensure non-negative result
        if (F[x] < 0) {
            F[x] += M;
        }
    }

    cout << (F[n] % M + M) % M << endl;

    return 0;
