        int threshold = (int)sqrt(step) + 1;
        int intermediate = running_total;

        for (int divisor = 2; divisor < threshold; divisor++) {
            intermediate = mod_operation("add", intermediate, sequence[step / divisor]);
        }

        int previous_limit = step;
        for (int counter = 1; counter <= step / threshold; counter++) {
            int next_limit = step / (counter + 1);
            int temp = mod_operation("mul", previous_limit - next_limit, sequence[counter]);
            if (counter == 1) {
                intermediate = mod_operation("add", intermediate, sequence.back());
            } else {
                intermediate = mod_operation("add", intermediate, temp);
