void solve() {
    long long P, K;
    cin >> P >> K;

    if (K == 0) {
        cout << modPow(P, P - 1, MOD) << endl;
        return;
    }
    if (K == 1) {
        cout << modPow(P, P, MOD) << endl;
        return;
    }

