    for (int i = 0; i < P; i++) {
        k_func[i] = (K * i) % P;
    }

    // Cycle detection
    vector<bool> visited(P, false);
    vector<int> cycle_histogram(P, 0);
    long long answer = 1;

    for (int idx = 0; idx < P; idx++) {
        if (visited[idx]) {
            continue;
        }

        // Follow the chain to find cycle length
        int length = 0;
        int pos = idx;
        while (!visited[pos]) {
            visited[pos] = true;
            pos = k_func[pos];
            length++;
        }

        if (length > 0) {
            cycle_histogram[length]++;
        }
    }

    // Final computation
    for (int cycle_size = 2; cycle_size < P; cycle_size++) {
        int count = cycle_histogram[cycle_size];
        if (count > 0) {
            long long base = (long long)cycle_size * count + 1;
            answer = (answer * modPow(base, count, MOD)) % MOD;
        }
    }

    cout << answer << endl;
}

