#include <cmath>
using namespace std;

const long long MOD = 1000000007;

long long modPow(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

void execute() {
    long long P, K;
    cin >> P >> K;

    // Handle trivial K values
    if (K == 0) {
        cout << modPow(P, P - 1, MOD) << endl;
        return;
    }
    if (K == 1) {
        cout << modPow(P, P, MOD) << endl;
        return;
    }

    // Build the transformation function
    vector<long long> transform(P);
    for (long long i = 0; i < P; i++) {
        transform[i] = (K * i) % P;
    }

    // Detect cycles and count their frequencies
    vector<bool> marked(P, false);
    vector<long long> cycle_counter(P, 0);
    long long final_val = 1;

    for (long long start = 0; start < P; start++) {
        if (marked[start]) {
            continue;
        }

        // Walk through the cycle
        long long steps = 0;
        long long current = start;
        while (!marked[current]) {
            marked[current] = true;
            current = transform[current];
            steps++;
        }

        if (steps > 0) {
            cycle_counter[steps]++;
        }
    }

    // Calculate result using cycle data
    for (long long size = 2; size < P; size++) {
        long long occurrences = cycle_counter[size];
        if (occurrences > 0) {
            long long temp = size * occurrences + 1;
            final_val = (final_val * modPow(temp, occurrences, MOD)) % MOD;
        }
    }

    cout << final_val << endl;
}

