            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

void solve() {
    int P, K;
    cin >> P >> K;

    if (K == 0) {
        cout << modPow(P, P - 1, MOD) << endl;
        return;
    }

    // Build the mapping: f(x) = (K * x) % P
    vector<int> mapping(P);
    for (int x = 0; x < P; x++) {
        mapping[x] = (int)((long long)K * x % P);
    }

    // Track visited nodes and count cycle lengths
    vector<bool> visited(P, false);
    vector<int> cycle_counts(P, 0);

    for (int start = 0; start < P; start++) {
        if (visited[start]) {
            continue;
        }

        // Traverse the cycle starting from 'start'
        int length = 0;
        int current = start;
        while (!visited[current]) {
            visited[current] = true;
            current = mapping[current];
            length++;
        }

        if (length < P) {
            cycle_counts[length]++;
        } else {
            cycle_counts[P-1]++;
        }
    }

