#include <cmath>
using namespace std;

const long long M = 1000000007;

long long modPow(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

void process() {
    int P, K;
    cin >> P >> K;

    vector<int> k(P);
    for (int x = 0; x < P; x++) {
        k[x] = (K * x) % P;
    }

    if (!K) {
        cout << modPow(P, P - 1, M) << endl;
        return;
    }

    vector<int> f(P, 0);
    vector<long long> c(P, 0);
    long long ans = 1;

    for (int i = 0; i < P; i++) {
        if (f[i]) continue;

        int cnt = 1;
        int u = i;
        f[u] = 1;
        while (!f[k[u]]) {
            u = k[u];
            f[u] = 1;
            cnt++;
        }

        if (cnt < P) {
            c[cnt]++;
        } else {
            c[cnt]++;
        }
    }

    for (int i = 1; i < P; i++) {
        if (c[i] != 0) {
            long long cnt = (long long)i * c[i] + (i > 1 ? 1 : 0);
            ans = (ans * modPow(cnt, c[i], M)) % M;
        }
    }

    cout << ans << endl;
}

int main() {
    int T = 1;
    while (T--) {
        process();
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>
using namespace std;

const long long MOD = 1000000007;

long long modPow(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

void solve() {
    long long P, K;
    cin >> P >> K;

    if (K == 0) {
        cout << modPow(P, P - 1, MOD) << endl;
        return;
    }

    // Build the mapping: x -> (K * x) % P
    vector<long long> mapping(P);
    for (long long x = 0; x < P; x++) {
        mapping[x] = (K * x) % P;
    }

    vector<bool> visited(P, false);
    vector<long long> cycle_counts(P, 0);
    long long result = 1;

    for (long long start = 0; start < P; start++) {
        if (visited[start]) {
            continue;
        }

        // Trace the cycle starting from 'start'
        long long length = 0;
        long long current = start;
        while (!visited[current]) {
            visited[current] = true;
            current = mapping[current];
            length++;
        }

        cycle_counts[length]++;
    }

    // Compute the answer using cycle information
    for (long long cycle_len = 1; cycle_len < P; cycle_len++) {
        long long count_of_cycles = cycle_counts[cycle_len];
        if (count_of_cycles == 0) {
            continue;
        }

        long long effective_length = cycle_len * count_of_cycles;
        if (cycle_len > 1) {
            effective_length += 1;
        }

        result = (result * modPow(effective_length, count_of_cycles, MOD)) % MOD;
    }

    cout << result << endl;
}

int main() {
    int T = 1;
    for (int i = 0; i < T; i++) {
