    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    int T = 1;

    while (T--) {
        long long P, K;
        cin >> P >> K;

        if (K == 0) {
            cout << modPow(P, P - 1, MOD) << endl;
            continue;
        }

        // Precompute the permutation induced by multiplication by K mod P
        vector<int> perm(P);
        for (int i = 0; i < P; i++) {
            perm[i] = (K * i) % P;
        }

        // Find cycle decomposition
        vector<bool> visited(P, false);
        vector<vector<int>> cycles;

        for (int i = 0; i < P; i++) {
            if (visited[i]) {
                continue;
            }
            vector<int> cycle;
            int j = i;
            while (!visited[j]) {
                visited[j] = true;
                cycle.push_back(j);
                j = perm[j];
            }
            cycles.push_back(cycle);
        }

        // Count cycles by length
        map<int, int> length_counts;
        for (const auto& cycle : cycles) {
            length_counts[cycle.size()]++;
        }

        long long ans = 1;
        for (const auto& entry : length_counts) {
            int length = entry.first;
            int count = entry.second;
            long long effective;
            if (length == 1) {
