        long long mid = low + (high - low) / 2;

        if (n <= mid) {
            if (move == 0) {
                ans += 1;
                move ^= 1;
            } else {
                ans += (1LL << h); // 2^h
            }
            high = mid;
        } else {
            if (move == 1) {
                ans += 1;
                move ^= 1;
            } else {
                ans += (1LL << h); // 2^h
            }
            low = mid + 1;
        }

        h--;
    }

    cout << ans << endl;

