    while (low < high) {
        long long mid = low + (high - low) / 2;

        if (n <= mid) {
            ans += (move == 0) ? 1 : (1LL << h);
            move ^= 1;
            high = mid;
        } else {
            ans += (move == 1) ? 1 : (1LL << h);
            move ^= 1;
            low = mid + 1;
        }

        h--;
    }

    cout << ans << endl;

    return 0;
}

