        sl.push_back(sl.back() + (1LL << (i + 1)));
    }

    long long h, n;
    cin >> h >> n;

    auto build_ancestry = [](long long x) {
        vector<long long> path;
        path.push_back(x);
        while (x > 1) {
            x >>= 1;
            path.push_back(x);
        }
        return path;
    };

