            if (flip) {
                curr += 1;
            }
            flip = !flip;
        }
        if (curr == n) {
            total += h;
            break;
        }

        temp_path.push_back(curr);
        reverse(temp_path.begin(), temp_path.end());

        bool found = false;
        for (int idx = 1; idx <= h; idx++) {
            if (nl[idx] == temp_path[idx]) {
