int main() {
    int h, n;
    cin >> h >> n;

    // Convert (n-1) to binary string
    int num = n - 1;
    string N = "";
    if (num == 0) {
        N = "0";
    } else {
        while (num > 0) {
            N = (char)('0' + (num % 2)) + N;
            num /= 2;
        }
    }

    // Pad with leading zeros to length h
    while (N.length() < h) {
        N = "0" + N;
    }

    long long ans = 0;
    bool f = false;

    for (int i = 0; i < h; i++) {
        char expected = (!f) ? '1' : '0';
        if (N[i] != expected) {
            f = !f;
            ans += 1;
        } else {
            ans += pow(2, h - i);
        }
    }

    cout << ans << endl;

    return 0;
}

