#include <regex>

int main() {
    std::string s;
    std::getline(std::cin, s);

    // Replace all occurrences of "dot" (except at the very start or end) with '.'
    while (true) {
        std::regex pattern("(?<!^)dot(?!$)");
        std::smatch match;
        if (!std::regex_search(s, match, pattern)) {
            break;
        }
        size_t pos = match.position(0);
        s = s.substr(0, pos) + '.' + s.substr(pos + 3);
    }

    // Replace first occurrence of "at" (except at the very start or end) with '@'
    std::regex at_pattern("(?<!^)at(?!$)");
    std::smatch at_match;
    if (std::regex_search(s, at_match, at_pattern)) {
        size_t pos = at_match.position(0);
        s = s.substr(0, pos) + '@' + s.substr(pos + 2);
    }

    std::cout << s << std::endl;
    return 0;
}

