std::string transform_string() {
    std::string dot = "dot";

    // Read input and replace 'dot' with '.'
    std::string s;
    std::getline(std::cin, s);

    // Replace all occurrences of "dot" with "."
    size_t pos = 0;
    while ((pos = s.find(dot, pos)) != std::string::npos) {
        s.replace(pos, dot.length(), ".");
        pos += 1; // Move past the replaced character
    }

    // Process the string: keep first char, replace 'at' with '@' once in the rest
    if (s.length() > 0) {
        char first_char = s[0];
        std::string rest = s.substr(1);

        // Replace first occurrence of "at" with "@"
        size_t at_pos = rest.find("at");
        if (at_pos != std::string::npos) {
            rest.replace(at_pos, 2, "@");
        }

        s = first_char + rest;
    }

    // Handle leading dot
    if (s.length() > 0 && s[0] == '.') {
        s = dot + s.substr(1);
    }

    // Handle trailing dot
    if (s.length() > 0 && s[s.length() - 1] == '.') {
        s = s.substr(0, s.length() - 1) + dot;
    }

    return s;
}

