int main() {
    int n, m;
    cin >> n >> m;

    vector<int> a(20);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    vector<int> left_sums;
    int left_size = n / 2 + n % 2;

    for (int mask = 0; mask < (1 << left_size); mask++) {
        int total = 0;
        int temp = mask;
        for (int idx = 0; idx < left_size; idx++) {
            if (temp & 1) {
                total += a[idx];
            }
            temp >>= 1;
        }
        left_sums.push_back(total % m);
    }

    sort(left_sums.begin(), left_sums.end());

    int result = 0;
    int right_size = n / 2;

    for (int mask = 0; mask < (1 << right_size); mask++) {
        int total = 0;
        int temp = mask;
        for (int idx = 0; idx < right_size; idx++) {
            if (temp & 1) {
                total += a[left_size + idx];
            }
            temp >>= 1;
        }
        total %= m;

        int complement = m - total - 1;
        auto pos = lower_bound(left_sums.begin(), left_sums.end(), complement);

        int candidate = left_sums.back();
        if (pos != left_sums.end()) {
            if (*pos > complement) {
                if (pos != left_sums.begin()) {
                    candidate = *(pos - 1);
                }
            } else {
                candidate = *pos;
            }
        }

        int candidate1 = (total + candidate) % m;
        int candidate2 = (total + left_sums.back()) % m;
        result = max(result, max(candidate1, candidate2));
    }

    cout << result % m << endl;

    return 0;
}

