#include <iostream>
#include <vector>
#include <algorithm>
#include <set>
#include <array>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    vector<long long> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    vector<long long> a1, a2;
    int n1 = n / 2;

    // Generate all subset sums for first half
    function<void(int, long long)> sums1 = [&](int i, long long sum) {
        if (i == n1) {
            a1.push_back(sum % m);
        } else {
            sums1(i + 1, (sum + a[i]) % m);
            sums1(i + 1, sum);
        }
    };

    // Generate all subset sums for second half
    function<void(int, long long)> sums2 = [&](int i, long long sum) {
        if (i == n) {
            a2.push_back(sum % m);
        } else {
            sums2(i + 1, (sum + a[i]) % m);
            sums2(i + 1, sum);
        }
    };

    sums1(0, 0);
    sums2(n1, 0);

    // Remove duplicates and sort a1
    set<long long> s(a1.begin(), a1.end());
    a1.assign(s.begin(), s.end());
    sort(a1.begin(), a1.end());

    long long ans = 0;

    for (long long i : a2) {
        // Find the largest element in a1 such that a1[j] + i < m
        auto it = lower_bound(a1.begin(), a1.end(), m - i);
        if (it != a1.begin()) {
            --it;
            if (ans < *it + i) {
                ans = *it + i;
            }
        }
    }

    cout << ans << endl;

