void generate_left_sums(const vector<int>& arr, int length, int mod, vector<int>& sums) {
    vector<pair<int, int>> stack;
    stack.push_back({0, 0}); // {index, current_sum}

    while (!stack.empty()) {
        auto [idx, current] = stack.back();
        stack.pop_back();

