int main() {
    int n, m;
    std::cin >> n >> m;

    std::vector<int> a(n);
    for (int i = 0; i < n; i++) {
        std::cin >> a[i];
    }

    int n1 = n / 2;
    std::vector<int> left_sums;
    std::vector<int> right_sums;

    auto compute_sums = [&](const std::vector<int>& arr, int start, int end, std::vector<int>& result_list) {
        std::stack<std::pair<int, int>> stack;
        stack.push({start, 0});

        while (!stack.empty()) {
            auto [idx, s] = stack.top();
            stack.pop();

            if (idx == end) {
                result_list.push_back(s % m);
            } else {
                stack.push({idx + 1, (s + arr[idx]) % m});
                stack.push({idx + 1, s});
            }
        }
    };

    compute_sums(a, 0, n1, left_sums);
    compute_sums(a, n1, n, right_sums);

    int ans = 0;
    std::set<int> left_set(left_sums.begin(), left_sums.end());
    left_sums.assign(left_set.begin(), left_set.end());
    std::sort(left_sums.begin(), left_sums.end());

    for (int r_val : right_sums) {
        int complement = m - r_val;
        auto it = std::lower_bound(left_sums.begin(), left_sums.end(), complement);

        if (it != left_sums.begin()) {
            int idx = it - left_sums.begin();
            int candidate = (left_sums[idx - 1] + r_val) % m;
            ans = std::max(ans, candidate);
        }

        if (it != left_sums.end()) {
            int idx = it - left_sums.begin();
