vector<int> get_subsequence_sums(const vector<int>& arr, int mod) {
    set<int> res;

    function<void(int, int)> backtrack = [&](int i, int cur) {
        if (i == arr.size()) {
            res.insert(cur % mod);
            return;
        }
        backtrack(i + 1, cur + arr[i]);
        backtrack(i + 1, cur);
    };

    backtrack(0, 0);
    return vector<int>(res.begin(), res.end());
}

