    vector<int> left = get_subsequence_sums(vector<int>(a.begin(), a.begin() + n1), m);
    vector<int> right = get_subsequence_sums(vector<int>(a.begin() + n1, a.end()), m);

    int best = 0;
    for (int r_val : right) {
        int target = m - r_val;
        int pos = lower_bound(left.begin(), left.end(), target) - left.begin();

        vector<int> indices = {pos - 1, pos};
        for (int idx : indices) {
            if (0 <= idx && idx < left.size()) {
                int candidate = (left[idx] + r_val) % m;
                if (candidate > best) {
                    best = candidate;
                }
            }
        }
    }

    cout << best << endl;

    return 0;
}

