int main() {
    int n, m;
    std::cin >> n >> m;

    std::vector<int> a(n);
    for (int i = 0; i < n; i++) {
        int x;
        std::cin >> x;
        a[i] = x % m;
    }

    auto compute_sums = [m](const std::vector<int>& arr) -> std::set<int> {
        std::set<int> sums;
        std::stack<std::pair<int, int>> stack;
        stack.push({0, 0});

        while (!stack.empty()) {
            int idx = stack.top().first;
            int cur_sum = stack.top().second;
            stack.pop();

            if (idx == static_cast<int>(arr.size())) {
                sums.insert(cur_sum % m);
            } else {
                stack.push({idx + 1, (cur_sum + arr[idx]) % m});
                stack.push({idx + 1, cur_sum});
            }
        }
        return sums;
    };

    int mid = n / 2;
    std::set<int> left_set = compute_sums(std::vector<int>(a.begin(), a.begin() + mid));
    std::set<int> right_set = compute_sums(std::vector<int>(a.begin() + mid, a.end()));

    std::vector<int> right_list(right_set.begin(), right_set.end());
    std::sort(right_list.begin(), right_list.end());

    int best = 0;

    for (int s : left_set) {
        int needed = m - s;
        auto pos_it = std::lower_bound(right_list.begin(), right_list.end(), needed);
        int pos = pos_it - right_list.begin();

        for (int offset = -1; offset <= 0; offset++) {
            if (0 <= pos + offset && pos + offset < static_cast<int>(right_list.size())) {
                int total = s + right_list[pos + offset];
                if (total > best) {
                    best = total;
                }
            }
        }
    }

    std::cout << best << std::endl;

    return 0;
}

