    int hi = l.size() - 1;
    int ans = 0;
    while (lo <= hi) {
        int mi = (lo + hi) >> 1;
        if (l[mi] < x) {
            ans = l[mi];
            lo = mi + 1;
        } else {
            hi = mi - 1;
        }
    }
    return ans;
}

