using namespace std;

int binary_search_leq(vector<int>& arr, int target) {
    int left = 0, right = arr.size() - 1;
    int result = 0;
    while (left <= right) {
        int mid = (left + right) / 2;
        if (arr[mid] < target) {
            result = arr[mid];
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return result;
}

int main() {
    int n, m;
    cin >> n >> m;

    vector<int> arr(n);
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }

    vector<int> half1, half2;
    for (int i = 0; i < n / 2; i++) {
        half1.push_back(arr[i]);
    }
    for (int i = n / 2; i < n; i++) {
        half2.push_back(arr[i]);
    }

    int size1 = half1.size();
    int size2 = half2.size();

    vector<int> sub_sums1;
    for (int mask = 0; mask < (1 << size1); mask++) {
        int total = 0;
        for (int i = 0; i < size1; i++) {
            if (mask & (1 << i)) {
                total += half1[i];
            }
        }
        sub_sums1.push_back(total % m);
    }

    vector<int> sub_sums2;
    for (int mask = 0; mask < (1 << size2); mask++) {
        int total = 0;
        for (int i = 0; i < size2; i++) {
            if (mask & (1 << i)) {
                total += half2[i];
            }
        }
        sub_sums2.push_back(total % m);
    }

    sort(sub_sums1.begin(), sub_sums1.end());
    sort(sub_sums2.begin(), sub_sums2.end());

    int max_mod = 0;

    for (int val : sub_sums1) {
        int needed = (m - val) % m;
        int candidate = binary_search_leq(sub_sums2, needed);
        int current = (val + candidate) % m;
        if (current > max_mod) {
            max_mod = current;
        }
    }

    cout << max_mod << endl;

    return 0;
}

