class Factorial {
private:
    int MOD;
    vector<long long> factorials;
    vector<long long> invModulos;
    vector<long long> invFactorial_;

public:
    Factorial(int MOD) : MOD(MOD), factorials({1, 1}), invModulos({0, 1}), invFactorial_({1, 1}) {}

    long long calc(int n) {
        if (n <= -1) {
            cerr << "Invalid argument to calculate n!" << endl;
            cerr << "n must be non-negative value. But the argument was " << n << endl;
            exit(1);
        }
        if (n < (int)factorials.size()) return factorials[n];
        int initialI = factorials.size();
        factorials.resize(n + 1);
        long long prev = factorials[initialI - 1];
        for (int i = initialI; i <= n; ++i) {
            prev = factorials[i] = prev * i % MOD;
        }
        return factorials[n];
    }

    long long inv(int n) {
        if (n <= -1) {
            cerr << "Invalid argument to calculate n^(-1)" << endl;
            cerr << "n must be non-negative value. But the argument was " << n << endl;
            exit(1);
        }
        int p = MOD;
        int pi = n % p;
        if (pi < (int)invModulos.size()) return invModulos[pi];
        int initialI = invModulos.size();
        for (int i = initialI; i < min(p, n + 1); ++i) {
            long long next = -invModulos[p % i] * (p / i) % p;
            if (next < 0) next += p;
            invModulos.push_back(next);
        }
        return invModulos[pi];
    }

    long long invFactorial(int n) {
        if (n <= -1) {
            cerr << "Invalid argument to calculate (n^(-1))!" << endl;
            cerr << "n must be non-negative value. But the argument was " << n << endl;
            exit(1);
        }
        if (n < (int)invFactorial_.size()) return invFactorial_[n];
        inv(n);
        int initialI = invFactorial_.size();
        invFactorial_.resize(n + 1);
        long long prev = invFactorial_[initialI - 1];
        for (int i = initialI; i <= n; ++i) {
            prev = invFactorial_[i] = (prev * invModulos[i % MOD]) % MOD;
        }
        return invFactorial_[n];
    }
};

class Combination {
private:
    int MOD;
    Factorial factorial;

public:
    Combination(int MOD) : MOD(MOD), factorial(MOD) {}

    long long ncr(int n, int k) {
        if (k < 0 || n < k) return 0;
        k = min(k, n - k);
        return factorial.calc(n) * factorial.invFactorial(max(n - k, k)) % MOD * factorial.invFactorial(min(k, n - k)) % MOD;
    }
};

long long powm(long long a, long long n, long long m) {
    if (a == 1 || n == 0) return 1;
    if (n % 2 == 0) {
        long long s = powm(a, n / 2, m);
        return s * s % m;
    } else {
        return a * powm(a, n - 1, m) % m;
    }
}

int binarySearchCount(const vector<int>& arr, int n, int key) {
    int left = 0, right = n - 1, count = 0;
    while (left <= right) {
        int mid = (right + left) / 2;
        if (arr[mid] <= key) {
            count = mid + 1;
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return count;
}

int countGreater(const vector<int>& arr, int n, int k) {
    int l = 0, r = n - 1, leftGreater = n;
    while (l <= r) {
        int m = l + (r - l) / 2;
        if (arr[m] >= k) {
            leftGreater = m;
            r = m - 1;
        } else {
            l = m + 1;
        }
    }
    return (n - leftGreater);
}

