    }
};

int powm(int a, int n, int m) {
    if (a == 1 || n == 0) return 1;
    if (n % 2 == 0) {
        int s = powm(a, n / 2, m);
        return (long long)s * s % m;
    } else {
        return (long long)a * powm(a, n - 1, m) % m;
    }
}

int binarySearchCount(const vector<int>& arr, int n, int key) {
    int left = 0, right = n - 1, count = 0;
    while (left <= right) {
        int mid = (right + left) / 2;
        if (arr[mid] <= key) {
            count = mid + 1;
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return count;
}

