public:
    Factorial(int MOD) : MOD(MOD), factorials({1, 1}), invModulos({0, 1}), invFactorial_({1, 1}) {}

    int calc(int n) {
        if (n <= -1) {
            cerr << "Invalid argument to calculate n!" << endl;
            exit(1);
        }
        if (n < (int)factorials.size()) return factorials[n];
        int prev = factorials.back();
        for (int i = factorials.size(); i <= n; ++i) {
            factorials.push_back((long long)prev * i % MOD);
            prev = factorials.back();
        }
        return factorials[n];
    }

    int inv(int n) {
        if (n <= -1) {
            cerr << "Invalid argument to calculate n^(-1)" << endl;
            exit(1);
