        int p = MOD;
        int pi = n % p;
        if (pi < (int)invModulos.size()) return invModulos[pi];
        for (int i = invModulos.size(); i < min(p, n + 1); ++i) {
            int next = -invModulos[p % i] * (p / i) % p;
            if (next < 0) next += p;
            invModulos.push_back(next);
        }
        return invModulos[pi];
    }

    int invFactorial(int n) {
        if (n <= -1) {
            cerr << "Invalid argument to calculate (n^(-1))!" << endl;
            exit(1);
        }
        if (n < (int)invFactorial_.size()) return invFactorial_[n];
        inv(n);
        int prev = invFactorial_.back();
        for (int i = invFactorial_.size(); i <= n; ++i) {
            int next = (long long)prev * invModulos[i % MOD] % MOD;
            invFactorial_.push_back(next);
            prev = next;
        }
        return invFactorial_[n];
    }
};

