def build_segment_tree(size):
    tree_size = 1
    while tree_size < size:
        tree_size *= 2
    return [0] * (tree_size * 2)

def update_segment(tree, index, value):
    pos = index + len(tree) // 2
    tree[pos] = value
    pos //= 2
    while pos > 0:
        tree[pos] = tree[pos * 2] + tree[pos * 2 + 1]
        pos //= 2

def range_query(tree, left, right):
    left += len(tree) // 2
    right += len(tree) // 2
    total = 0
    while left <= right:
        if left % 2 == 1:
            total += tree[left]
            left += 1
        if right % 2 == 0:
            total += tree[right]
            right -= 1
        left //= 2
        right //= 2
    return total

