#include <iostream>
#include <vector>
#include <set>
#include <cmath>
using namespace std;

vector<int> factor(int n) {
    vector<int> res;
    int d = 2;
    while (d * d <= n) {
        while (n % d == 0) {
            res.push_back(d);
            n /= d;
        }
        d++;
    }
    if (n > 1) {
        res.push_back(n);
    }
    return res;
}

int phi(int n) {
    vector<int> ps_vec = factor(n);
    set<int> ps(ps_vec.begin(), ps_vec.end());
    int x = n;
    for (int p : ps) {
        x = x / p * (p - 1);
    }
    return x;
}

long long prod_mod(int a, int b, int m) {
    long long r = 1;
    for (int i = a + 1; i <= b; i++) {
        r = (r * i) % m;
    }
    return r;
}

vector<int> init_seg(int n) {
    int sz = 1;
    while (sz < n) {
        sz *= 2;
    }
    return vector<int>(2 * sz, 0);
}

void seg_upd(vector<int>& tree, int i, int v) {
    int p = i + tree.size() / 2;
    tree[p] = v;
    p /= 2;
    while (p) {
        tree[p] = tree[2 * p] + tree[2 * p + 1];
        p /= 2;
    }
}

int seg_qry(vector<int>& tree, int a, int b) {
    a += tree.size() / 2;
    b += tree.size() / 2;
    long long s = 0;
    while (a <= b) {
        if (a % 2 == 1) {
            s += tree[a];
            a += 1;
        }
        if (b % 2 == 0) {
            s += tree[b];
            b -= 1;
        }
        a /= 2;
        b /= 2;
    }
    return (int)s;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, mod;
    cin >> n >> mod;

    int phi_n = phi(mod);
    int L = n + 5;
    vector<long long> facts(L + 1, 1);
    for (int i = 1; i <= L; i++) {
        facts[i] = (i * facts[i - 1]) % mod;
    }

    if (n <= 3) {
        cout << 0 << endl;
    } else {
        vector<int> dp(2000, 0);
        dp[0] = 1;
        dp[1] = 2;
        dp[2] = 2;
        dp[3] = 1;
        vector<int> seg = init_seg(2005);
        for (int i = 0; i < 4; i++) {
            seg_upd(seg, i, dp[i]);
        }
        int mx = 3;
        long long ans = 0;
        for (int it = 0; it < n - 3; it++) {
            vector<int> prev = dp;
            long long tmp = 0;
            for (int j = 0; j < it + 3; j++) {
                for (int k = 1; k < mx + 2; k++) {
                    int cnt = seg_qry(seg, j + k + 1, 2004);
                    tmp = (tmp + (long long)cnt * prev[k - 1]) % mod;
                    dp[j + k] = (dp[j + k] + prev[k - 1]) % mod;
                    seg_upd(seg, j + k, dp[j + k]);
                }
            }
            mx += it + 3;
            long long p = prod_mod(it + 3, n, mod);
            ans = (ans + p * tmp) % mod;
        }
        cout << ans << endl;
    }

    return 0;
}

