            if (dp[i-1].find(x) == dp[i-1].end()) {
                continue;
            }
            long long base_val = dp[i-1][x];
            for (long long d = -i + 1; d < i; d++) {
                long long new_val = (dp[i][x + d] + base_val * (i - abs(d))) % mod;
                dp[i][x + d] = new_val;
            }
