        long long low_bound = m - (i - 1) * (i - 2) / 2;
        long long high_bound = m + (i - 1) * (i - 2) / 2;

        // First loop: multiply previous dp1 by i
        for (long long x = low_bound; x <= high_bound; x++) {
            if (dp1[i-1].find(x) != dp1[i-1].end()) {
