            auto it = dp.find({i-1, x_key});
            if (it == dp.end() || it->second == 0) continue;
            long long prev_val = it->second;

            for (long long d = -i + 1; d < i; d++) {
                pair<long long, long long> key = {i, x_key + d};
                long long contribution = prev_val * (i - abs(d));
                new_dp[key] = (new_dp[key] + contribution) % mod;
            }
        }

        // Process dp1
        map<pair<long long, long long>, long long> new_dp1;

        // First part: multiplication by i
        for (long long x_key = m - span; x_key <= m + span; x_key++) {
            auto it = dp1.find({i-1, x_key});
            if (it == dp1.end() || it->second == 0) continue;
            long long prev_val = it->second;

            pair<long long, long long> key = {i, x_key};
            new_dp1[key] = (new_dp1[key] + prev_val * i) % mod;
        }

        // Second part: adding contributions
        for (long long x_key = m - span; x_key <= m + span; x_key++) {
            auto it = dp.find({i-1, x_key});
            if (it == dp.end() || it->second == 0) continue;
            long long prev_val = it->second;

            for (long long d = 1; d < i; d++) {
                pair<long long, long long> key = {i, x_key - d};
                long long contribution = prev_val * (i - d);
                new_dp1[key] = (new_dp1[key] + contribution) % mod;
            }
        }

        dp = new_dp;
        dp1 = new_dp1;
    }

    // Sum contributions from dp1 at level n where position > m
    long long result = 0;
    for (auto& p : dp1) {
        if (p.first.first == n && p.first.second > m) {
            result = (result + p.second) % mod;
        }
    }

    return result;
}

