int main() {
    long long n, mod;
    cin >> n >> mod;

    long long m = n * (n - 1) / 2;

    // Function to get bounds
    auto get_bounds = [&](long long i) -> pair<long long, long long> {
        long long span = (i - 1) * (i - 2) / 2;
        return {m - span, m + span};
    };

    // Initialize with vectors sized to the max needed bounds
    long long max_bound = n * (n - 1) + 1;

    vector<vector<long long>> dp(n + 1, vector<long long>(max_bound, 0));
    vector<vector<long long>> dp1(n + 1, vector<long long>(max_bound, 0));

    dp[1][m] = 1;

    // Iterate through all levels
    for (long long i = 2; i <= n; i++) {
        auto bounds = get_bounds(i);
        long long low = bounds.first;
        long long high = bounds.second;

        for (long long x = low; x <= high; x++) {
            if (dp[i-1][x] == 0) continue;
            long long base_val = dp[i-1][x];

            for (long long d = -i + 1; d < i; d++) {
                dp[i][x + d] = (dp[i][x + d] + base_val * (i - abs(d))) % mod;
            }
        }

        // Process dp1 for this level
        auto prev_bounds = get_bounds(i-1);
        long long low_prev = prev_bounds.first;
        long long high_prev = prev_bounds.second;

        // Multiply previous dp1 by i
        for (long long x = low_prev; x <= high_prev; x++) {
            if (dp1[i-1][x] != 0) {
                dp1[i][x] = (dp1[i][x] + dp1[i-1][x] * i) % mod;
            }
        }

        // Add contributions from dp[i-1]
        for (long long x = low_prev; x <= high_prev; x++) {
            if (dp[i-1][x] == 0) continue;
            long long base_val = dp[i-1][x];

            for (long long d = 1; d < i; d++) {
                dp1[i][x - d] = (dp1[i][x - d] + base_val * (i - d)) % mod;
            }
        }
    }

    // Calculate result as sum of dp1[n][x] for x > m
    long long result = 0;
    for (long long x = m + 1; x <= n * (n - 1); x++) {
        result = (result + dp1[n][x]) % mod;
    }

    cout << result << endl;

    return 0;
}

