    }

    long long last_ans = 17;
    long long ans = 17;
    int size = (n - 1) * (n - 2) / 2 + 1;

    // Initialize record with explicit indices
    vector<vector<long long>> record(2, vector<long long>(size + 1, 0));
    vector<long long> initial = {1, 2, 2, 1};
    for (int i = 0; i < 4; i++) {
        record[0][i] = initial[i];
    }

    int inv = 0;

