        long long cum = 0;
        for (int i = 0; i < m; i++) {
            cum += record[inv ^ 1][i];
            record[inv][i] = cum % mod;
        }

        // Second loop: sliding window
        for (int i = m; i <= tp_size / 2; i++) {
            cum += record[inv ^ 1][i];
            cum -= record[inv ^ 1][i - m];
            record[inv][i] = cum % mod;
        }

        // Third loop: reflection
        for (int i = 0; i <= tp_size / 2; i++) {
            record[inv][tp_size - i] = record[inv][i];
        }

        // Fourth loop: contribution calculation
