long long go(int n, int h, std::map<std::pair<int, int>, long long>& v) {
    std::pair<int, int> key = std::make_pair(n, h);
    if (v.find(key) == v.end()) {
        if (n == 0) {
            v[key] = 1;
        } else if (h == 0) {
            v[key] = 0;
        } else {
