    vector<vector<long long>> dp(n + 1, vector<long long>(n + 1, -1));

    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= n; j++) {
            dp[i][j] = fill(i, j);
        }
    }

    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= n; j++) {
            t(i, j, dp);
        }
    }

