        end = line.find(' ', start);
    }
    tokens.push_back(line.substr(start));

    int n = stoi(tokens[0]);
    int h = stoi(tokens[1]);

    // Initialize DP table with zeros
    vector<vector<long long>> dp(36, vector<long long>(36, 0));
    dp[0][0] = 1;  // Empty tree

    // Fill DP table
    for (int nodes = 1; nodes < 36; nodes++) {
        for (int minheight = 0; minheight <= nodes; minheight++) {
            long long total = 0;
            for (int topnode = 1; topnode <= nodes; topnode++) {
                int left_nodes = topnode - 1;
                int right_nodes = nodes - topnode;

                long long left_total = dp[left_nodes][0];
