                long long left_min_h = dp[left_nodes][left_min_h_index];
                long long right_min_h = dp[right_nodes][right_min_h_index];

                total += left_total * right_total - (left_total - left_min_h) * (right_total - right_min_h);
            }
            dp[nodes][minheight] = total;
        }
