    }

    int n_val = inputs[0];
    int h_val = inputs[1];

    // Initialize 2D vector for dynamic programming
    std::vector<std::vector<long long>> min_tree_count(36, std::vector<long long>(36, 0));
    min_tree_count[0][0] = 1;

    // Fill table for binary tree counts
    for (int num_nodes = 1; num_nodes < 36; num_nodes++) {
        for (int min_h = 0; min_h <= num_nodes; min_h++) {
            long long accum = 0;
            for (int root_pos = 1; root_pos <= num_nodes; root_pos++) {
                int left_part = root_pos - 1;
                int right_part = num_nodes - root_pos;

                long long left_all = min_tree_count[left_part][0];
                long long right_all = min_tree_count[right_part][0];
                int left_min_idx = std::max(min_h - 1, 0);
