                long long left_min = min_tree_count[left_part][left_min_idx];
                long long right_min = min_tree_count[right_part][right_min_idx];

                accum += (left_all * right_all - 
                         (left_all - left_min) * (right_all - right_min));
            }
            min_tree_count[num_nodes][min_h] = accum;
        }
