    // Compute values using DP
    for (int total = 1; total < 36; ++total) {
        for (int height = 0; height <= total; ++height) {
            long long s = 0;
            for (int r = 1; r <= total; ++r) {
                int l_nodes = r - 1;
                int rt_nodes = total - r;

                long long l_0 = table[l_nodes][0];
                long long r_0 = table[rt_nodes][0];
                long long l_hm1 = table[l_nodes][std::max(height - 1, 0)];
                long long r_hm1 = table[rt_nodes][std::max(height - 1, 0)];

                s += l_0 * r_0 - (l_0 - l_hm1) * (r_0 - r_hm1);
            }
            table[total][height] = s;
        }
    }

    std::cout << table[n][h] << std::endl;

    return 0;
