    int n, h;
    ss >> n >> h;

    // Initialize dp table with -1
    vector<vector<long long>> dp(n + 1, vector<long long>(n + 1, -1));
    dp[0][0] = 1;

    // Memoized recursive function using lambda
    function<long long(int, int)> f = [&](int n_val, int h_val) -> long long {
        if (dp[n_val][h_val] != -1) {
            return dp[n_val][h_val];
        }

        long long result;
        if (n_val == 0) {
            result = 0;
        } else if (h_val == 0) {
            result = f(n_val, 1);
        } else {
            result = 0;
            for (int i = 0; i < n_val; i++) {
                long long term1 = f(n_val - i - 1, 0) * f(i, h_val - 1);
                long long term2 = f(n_val - i - 1, h_val - 1) * f(i, 0);
                long long term3 = f(n_val - i - 1, h_val - 1) * f(i, h_val - 1);
                result += term1 + term2 - term3;
            }
        }

        dp[n_val][h_val] = result;
        return result;
    };

